#!/usr/bin/env python3
# luxarch:luxpm-close-tracks-deferrals hook v6 - DO NOT edit this file - it is emitted by `luxarch --emit hooks`; re-emit to update.
"""Deny a close summary that defers work without naming the issue that tracks it.

PreToolUse(luxpm_update_issue, luxpm_create_issue): every `close_summary` the call writes (the
single form, each `updates[]` entry, a create filed as done) is read sentence by sentence. A
sentence that defers work ("not built", "deferred", "follow-up", "out of scope", "stated limit",
"next release", "UNREPRODUCED", …) must name another issue's key (`<ticket>`) or say `dropped`
with its reason. A lead-in that defers ("**Not built:**") hands that duty to each bullet under it,
and a deferring sentence may hand it to the next one ("Not built: X. That's AB-12."). Words inside a
code span with no space (`[rules.deferred]`) and luxarch's own `0 xfail (deferred)` are a name, not
prose, and a `Follow-up (<sha>):` names the commit that shipped it.

A sentence that says nothing remains defers nothing, when the WHOLE sentence is made of the fixed
words of one of those forms: "Nothing deferred.", "No follow-ups.", "No follow-up needed.", "No stated
limits remain.", "Follow-ups: none.", "The open question is answered.". No form has a free-text
slot, since each such slot (a subject, a reason after a colon, trailing items) is where remaining
work rode through. A form inside a longer sentence clears nothing ("Nothing deferred aside from the
Windows port." is read as it always was), and a hurried "No time for follow-up." is denied. The
form may open with the commit or version that shipped the work, again in fixed words only:
"Shipped in `c83acc8`, both halves, nothing deferred.".

"Untested" says something still lacks a test, except in fixed shapes that report the opposite:
"Nothing is left untested." as the whole sentence or its last clause after a `;`, with nothing
before it in that clause; and a sentence whose subject is the untested part in the past ("the
untested half was …") that either ends "…, and it is now covered." (or tested) or opens with the
file's coverage rising ("`ws.py` 45% → 77% — the untested half was …"). Anything else around it
("The untested Windows build shipped.", "Almost nothing is left untested.") is read as before.

"Does not run" / "do not run" says where a check applies, not work left undone, only when the
sentence's subject is a rule, check, guard or hook ("The new rules are web-only and do not run on
this collector.") and a short complement ("on <place>", "here") ends the clause. Any other subject
("The migration does not run on staging"), a first-person writer, a past or passive form ("I did
not run …", "was not run") and "not run yet" are read as before.

"Unconfirmed" and "inconclusive" are a verdict or a claim left unchecked wherever they stand in
prose. An app whose own status word is one writes it in a code span (`UNCONFIRMED` orders,
`OrderStatus.UNCONFIRMED`), which is a name.

A removal says work is done, in fixed words with names in code spans only: "Left for the owner:
`ImageRole` is gone, and with it `analysis_priority`." Under "Follow-ups:" or "Open questions:" it
names the commit: "Follow-ups: `x` was removed in `a1b2c3d`."

A sentence that tells the ticket's history, the defect fixed or the commit that did a part of the
work is read like any other: each such reading needs a free-text slot, and a free-text slot carries
remaining work as easily as done work. A tracking sentence may also be the key in fixed words:
"AB-12 tracks it.".

`--scan FILE` reads a JSON object of `{"<KEY>": "<close summary>"}` and prints each untracked
deferral as `<KEY>: <sentence>`, exiting 1 when there is one and 2 when the file is not such an
object: `/luxpm-audit` runs it over a project's closed summaries.

**Why a hook.** A close summary lives on a closed issue, and a closed issue is in no open list,
no focus digest and no backlog sweep: work written only there is tracked by nothing. `/wrap-up`
said "every finding filed or dropped" in text, and an agent still wrote "Not built: …" twice into
a close summary and called it filed. The rule's home is `/wrap-up` step 6 ("A close summary is not
a tracker"); this makes it hold.

It reads only the text the call carries, so it cannot tell whether the cited key is open: citing
one is the agent's statement that it is, and the key is there for anyone to check. Fails OPEN on
input it cannot read: a hook that blocks on its own uncertainty gets switched off.
"""

from __future__ import annotations

import json
import re
import sys

_DEFERS = re.compile(
    r"\b(?:not\s+(?:yet\s+)?(?:built|done|fixed|implemented|handled|covered|shipped|filed|tracked"
    r"|verified|confirmed|checked|tested|run|taken|asked)"
    r"|did\s+not\s+(?:build|do|fix|ship|verify|check)|unconfirmed|inconclusive|unverified"
    r"|untested"
    r"|open\s+(?:owner\s+)?questions?|left\s+in\s+place"
    r"|deferred|defer(?:s|ring)?\b|follow[- ]?ups?\b"
    r"|a\s+future\s+(?:tightening|rule|check|release|cut|pass|version|change)"
    r"|out\s+of\s+scope|(?:stated|known)\s+(?:limits?|limitations?)\b"
    r"|left\s+(?:for|as\s+is|open)|for\s+later|(?:a|in\s+a)\s+later\s+(?:cut|release|pass|version)"
    r"|next\s+(?:release|cut|pass)|todo\b|unreproduced|not\s+reproduced"
    r"|still\s+(?:open|to\s+do|missing)|remains?\s+(?:open|to\s+(?:do|be))|(?:filed|tracked|handled)\s+separately)",
    re.IGNORECASE,
)
_KEY = re.compile(r"\b[A-Z][A-Z0-9]{1,15}-\d+\b")
_DROPPED = re.compile(r"\bdropped\b", re.IGNORECASE)
_BULLET = re.compile(r"^\s*(?:[-*+]|\d+[.)])\s+")
# A sentence ends at . ! or ? and the whitespace after it, after any closing bold or italic marks
# ("… amended.** The ticket"), whatever the next sentence opens with: a lowercase tool name
# (`luxarch is pinned …`), a digit or `[` starts a sentence of its own, and never borrows the key
# or the fixed form of the one before it (v5). An abbreviation's dot ends one too: a deferral
# never borrows a key across `e.g.` or `vs.`, and the cost is a sentence cut short, read alone.
_SENTENCE = re.compile(r"(?<=[.!?])((?:\*\*|\*|__|_)?)\s+")
# A code span with no space is a name, not prose (`[rules.deferred]`), and so is luxarch's own
# summary count `0 xfail (deferred)` (a count above 0 is deferred tests, and reads as such).
_CODE = re.compile(r"`[^`\s]+`|\b0\s+xfail\s+\(deferred\)", re.IGNORECASE)
_HEX = r"(?=[0-9a-f]*[a-f])(?=[0-9a-f]*[0-9])[0-9a-f]{7,40}"
# A follow-up that names the commit that shipped it: `Follow-up (<sha>)`.
_SHIPPED = re.compile(rf"follow[- ]?ups?\s*\([^)]*\b{_HEX}\b[^)]*\)", re.IGNORECASE)
_FOLLOW_UP = r"follow[- ]?ups?"
_REMAINDER = (
    rf"(?:{_FOLLOW_UP}|deferrals?|deferred\s+work|(?:stated|known)\s+limit(?:ation)?s?"
    r"|open\s+questions?)"
)
_NEEDED = r"(?:needed|required|remains?|remaining|left)"
_SHIPPED_ALL = r"(?:full\s+scope|everything|all\s+of\s+it|all)\s+shipped"
_JOIN = r"\s*[,;—–-]\s*"
# The commit or version that shipped it, as a fixed-word lead: "Shipped in `c83acc8`, both halves".
_REF = rf"`?(?:{_HEX}|v?\d+\.\d+\.\d+)`?"
_SHIPPED_IN = (
    rf"(?:shipped|landed|fixed|done|merged)(?:\s+in\s+(?:commit\s+)?{_REF}(?:\s*(?:,|\+|and)\s*{_REF})*)?"
    r"(?:\s*,\s*(?:both\s+halves|in\s+full|all\s+of\s+it|every\s+part|end\s+to\s+end))?"
)
# The sentences that say nothing remains, made of FIXED words only, and only as the WHOLE sentence.
# No slot takes free text, so no wording of remaining work can ride inside one: every form a past
# attack used for that (a free subject, a reason after a colon, trailing items) is not read here.
_NOTHING_LEFT = re.compile(
    rf"(?:(?:{_SHIPPED_ALL}|{_SHIPPED_IN}){_JOIN})?"
    r"(?:"
    r"(?:nothing|none)\s+(?:(?:is|was|has\s+been)\s+)?(?:being\s+)?(?:left\s+)?deferred"
    r"|nothing\s+was\s+deferred\s+and\s+nothing\s+is\s+left\s+open"
    rf"|no\s+(?:(?:further|new|additional|remaining|outstanding)\s+)?{_REMAINDER}(?:\s+work)?"
    rf"(?:\s+(?:or|and)\s+{_REMAINDER})?(?:\s+(?:(?:is|are|was|were)\s+)?{_NEEDED})?"
    rf"|there\s+(?:is|are)\s+no\s+{_REMAINDER}(?:\s+{_NEEDED})?"
    rf"|(?:{_REMAINDER}|deferred|not\s+built)\s*(?::|—|–|-)\s*(?:none|nothing|n/a)"
    r"(?:\s+(?:needed|required))?"
    rf"|{_REMAINDER}\s+(?:(?:is|are)\s+)?not\s+(?:needed|required)"
    r"|(?:(?:i|we)\s+)?(?:did\s+not|didn't)\s+defer\s+anything"
    rf"|(?:(?:i|we)\s+)?(?:will\s+not|won't)\s+need\s+an?\s+{_FOLLOW_UP}"
    r"|(?:the|all|every)\s+open\s+questions?(?:\s+on\s+this\s+(?:ticket|issue))?\s+"
    r"(?:(?:is|are|was|were)\s+)?(?:(?:therefore|now|all|already)\s+)?(?:answered|resolved|settled)"
    r")"
    rf"(?:{_JOIN}{_SHIPPED_ALL})?\s*[.!]?",
    re.IGNORECASE,
)
_POINTER = re.compile(
    r"^(?:[Tt]hat|[Tt]his|[Ii]t|[Tt]racked|[Ff]iled)\b"
    r"|^[A-Z][A-Z0-9]{1,15}-\d+\s+(?:tracks|covers|has)\s+(?:it|this|that)\s*[.!]?\s*$"
)

# A removal in fixed words, with names in code spans only: "`ImageRole` is gone, and with it `x`".
_CS = r"`[^`\s]+`"
_CS_LIST = rf"{_CS}(?:\s*(?:/|,|&|and)\s*{_CS})*"
_REMOVED = r"(?:is|are|was|were|has\s+been|have\s+been)\s+(?:gone|removed|deleted)"
_IN_COMMIT = rf"\s+in\s+(?:commit\s+)?`?{_HEX}`?"
_WITH_IT = rf"(?:\s*,?\s*(?:and\s+)?with\s+(?:it|them)\s+{_CS_LIST})?\s*[.!]?"
_GONE = re.compile(
    r"(?:(?:left\s+for\s+(?:the\s+)?(?:owner|maintainer)\s*:\s*)?"
    rf"{_CS_LIST}\s+{_REMOVED}(?:{_IN_COMMIT})?"
    rf"|(?:follow[- ]?ups?|open\s+questions?)\s*:\s*{_CS_LIST}\s+{_REMOVED}{_IN_COMMIT})"
    rf"{_WITH_IT}",
    re.IGNORECASE,
)


def _says_nothing_left(text: str) -> bool:
    """The whole sentence (a bullet's text, bold and curly apostrophes aside) is one of the fixed
    forms that say nothing remains."""
    s = text.replace("’", "'").replace("*", "").strip()
    return bool(_NOTHING_LEFT.fullmatch(_BULLET.sub("", s).strip()))


def _read(text: str) -> str:
    """The sentence as prose to check: names and the shipping commit taken out."""
    return _SHIPPED.sub("", text)


def _name(m: re.Match[str]) -> str:
    """A code span is a name; a commit in one stays readable as the commit."""
    inner = m.group(0).strip("`")
    return inner if re.fullmatch(_HEX, inner) else "``"


# "Nothing is left untested." as the whole sentence, or as its last clause after a `;`: fixed
# words, no qualifier before them ("Almost nothing …", "Except X, nothing …") and nothing after.
_NOTHING_UNTESTED = re.compile(
    r"(?:^|;\s*)nothing\s+(?:is\s+|was\s+)?(?:left\s+)?untested\s*[.!]?\s*$",
    re.IGNORECASE,
)
# The untested part as the subject of a past-tense clause, with the coverage added said of IT: the
# sentence ends "…, and it is now covered." (or tested), or it opens with the file's coverage
# rising ("`ws.py` 45% → 77% — the untested half was …").
_BEFORE_STATE = re.compile(
    r"\bthe\s+untested(?:\s+[\w.-]+){1,3}?\s+(?:was|were)\b", re.IGNORECASE
)
_NOW_COVERED = re.compile(
    r",?\s+and\s+(?:it|they)\s+(?:is|are)\s+now\s+(?:covered|tested)\s*[.!]?\s*$",
    re.IGNORECASE,
)
_COVERAGE_ROSE = re.compile(
    r"^\W*[\w./`-]+\W*\s+(\d+(?:\.\d+)?)\s*%\s*(?:→|->)\s*(\d+(?:\.\d+)?)\s*%\W*\s*(?:—|–|-|:)\s*the\s+untested\b",
    re.IGNORECASE,
)
_UNTESTED = re.compile(r"\buntested\b", re.IGNORECASE)
# A rule or check, the sentence's subject, that does not run on a kind of repo or place: where it
# applies, not work left undone. Only that subject, with a short complement ending the clause.
_DOES_NOT_APPLY = re.compile(
    r"^(?:the|this|these|those|both|each|its)(?:\s+[\w.-]+){0,3}?\s+(?:rules?|checks?|guards?|hooks?)\b"
    r"(?:(?!\b(?:i|we|our|us|you)\b)[^;.])*?\b(?:do|does)\s+not\s+run"
    r"(?=(?:\s+(?:on|in|for|against|outside|over)(?:\s+(?!(?:and|but|until|so|because|yet|now|anymore)\b)[\w./`'-]+){1,5}|\s+(?:here|there))\s*(?:[.;!]|$))",
    re.IGNORECASE,
)


def _scope_reported(prose: str) -> str:
    """The prose with a "do/does not run" that says where a rule or check applies taken out."""
    m = _DOES_NOT_APPLY.match(prose.strip())
    return prose.replace(m.group(0), " ", 1) if m else prose


def _untested_reported(prose: str) -> str:
    """The prose with an "untested" that reports coverage, not a gap, taken out."""
    text = prose.strip()
    if _NOTHING_UNTESTED.search(text) and len(_UNTESTED.findall(text)) == 1:
        return _UNTESTED.sub(" ", prose)
    if len(_UNTESTED.findall(text)) != 1 or not _BEFORE_STATE.search(text):
        return prose
    rose = _COVERAGE_ROSE.search(text)
    if _NOW_COVERED.search(text) or (
        rose and float(rose.group(1)) < float(rose.group(2))
    ):
        return _UNTESTED.sub(" ", prose)
    return prose


def _defers(text: str) -> bool:
    if _says_nothing_left(text):
        return False
    lead = _BULLET.sub("", text.replace("’", "'").replace("*", "")).strip()
    if _GONE.fullmatch(lead):
        return False
    prose = _scope_reported(_untested_reported(_read(_CODE.sub(_name, text))))
    return bool(_DEFERS.search(prose))


def _own_key(entry: dict[str, object], project: object) -> str:
    seq = str(entry.get("sequence_id") or "").strip().upper()
    if "-" in seq or not seq:
        return seq
    proj = str(entry.get("project") or project or "").strip().upper()
    return f"{proj}-{seq}" if proj else seq


def _tracked(text: str, own: str) -> bool:
    return bool(_DROPPED.search(text)) or any(k != own for k in _KEY.findall(text))


def _sentences(text: str) -> list[str]:
    """Split at each sentence end, keeping a closing bold or italic mark on its own sentence."""
    out: list[str] = []
    start = 0
    for m in _SENTENCE.finditer(text):
        out.append(text[start : m.end(1)])
        start = m.end()
    out.append(text[start:])
    return out


def untracked(summary: str, own: str) -> list[str]:
    """Each sentence (or bullet under a deferring lead-in) that defers work and names no other
    issue and no `dropped`."""
    out: list[str] = []
    lines = summary.splitlines()
    k = 0
    while k < len(lines):
        line = lines[k]
        k += 1
        plain = line.strip().strip("*_ ").rstrip("*_ ")
        if not plain:
            continue
        if _defers(plain) and plain.endswith(":") and not _tracked(plain, own):
            # a lead-in: each bullet under it (until a blank line or a non-bullet) carries the duty
            under = False
            while k < len(lines) and (
                _BULLET.match(lines[k]) or (under and lines[k].startswith((" ", "\t")))
            ):
                if _BULLET.match(lines[k]):
                    under = True
                    if not _tracked(lines[k], own):
                        out.append(lines[k].strip())
                k += 1
            if not under:
                out.append(plain)
            continue
        sentences = _sentences(plain)
        for i, sentence in enumerate(sentences):
            nxt = sentences[i + 1] if i + 1 < len(sentences) else ""
            handed = bool(_POINTER.match(nxt)) and _tracked(nxt, own)
            if _defers(sentence) and not _tracked(sentence, own) and not handed:
                out.append(sentence.strip())
    return out


def _closes(tool_input: dict[str, object]) -> list[tuple[str, str]]:
    entries: list[dict[str, object]] = [tool_input]
    updates = tool_input.get("updates")
    if isinstance(updates, list):
        entries += [u for u in updates if isinstance(u, dict)]
    project = tool_input.get("project")
    out: list[tuple[str, str]] = []
    for e in entries:
        summary = e.get("close_summary")
        if isinstance(summary, str) and summary.strip():
            out.append((_own_key(e, project), summary))
    return out


# One name for both, so the clause reads the same under every Python target (PEP 758).
_UNREADABLE = (OSError, ValueError, RecursionError)


def scan(path: str) -> int:
    try:
        with open(path, encoding="utf-8") as f:
            summaries = json.load(f)
    except _UNREADABLE:
        summaries = None
    if not isinstance(summaries, dict) or not all(
        v is None or isinstance(v, str) for v in summaries.values()
    ):
        print(
            '--scan reads a JSON object: {"<KEY>": "<close summary>" or null}',
            file=sys.stderr,
        )
        return 2
    found = [
        f"{key}: {s}"
        for key, summary in summaries.items()
        if isinstance(summary, str)
        for s in untracked(summary, str(key).upper())
    ]
    print("\n".join(found) if found else "no untracked deferrals")
    return 1 if found else 0


def main() -> int:
    if len(sys.argv) == 3 and sys.argv[1] == "--scan":
        return scan(sys.argv[2])
    try:
        ev = json.load(sys.stdin) or {}
        ti = ev.get("tool_input")
        closes = _closes(ti if isinstance(ti, dict) else {})
    except Exception:
        return 0  # hooks fail OPEN
    found = [(own, s) for own, summary in closes for s in untracked(summary, own)]
    if not found:
        return 0
    lines = "\n".join(f"  - {own or 'this issue'}: {s[:200]}" for own, s in found)
    print(
        "DENIED: this close summary defers work that no open issue tracks. A closed issue is in no "
        "open list, focus or backlog sweep, so work written only into its summary is lost:\n"
        f"{lines}\n"
        "For each: search LuxPM, then file it as its own open issue (or comment on the open one "
        "that covers it) and name that key in the sentence, e.g. `Not built: X (<ticket>)`. "
        "Work you decided against says `dropped: <why>` instead. Then close again. "
        'See /wrap-up step 6, "A close summary is not a tracker".',
        file=sys.stderr,
    )
    return 2


if __name__ == "__main__":
    sys.exit(main())
